const input=$input.first().json;
const session=typeof input.sessionId==='string'?input.sessionId:'';
const message=typeof input.chatInput==='string'?input.chatInput.trim():'';
const valid=/^[A-Za-z0-9_-]{16,128}$/.test(session)&&message.length>=1&&message.length<=4000;
return [{json:valid?{valid:true,session_id:session,turn_id:String($execution.id),message}:{valid:false,output:!(/^[A-Za-z0-9_-]{16,128}$/.test(session))?'Please start a new chat session and try again.':'Please send a message between 1 and 4,000 characters.'}}];

function safeNode(name){try{return $(name).isExecuted?$(name).first().json:null;}catch{return null;}}
function observation(value){
 if(typeof value==='string'){try{value=JSON.parse(value);}catch{return [];}}
 if(value&&typeof value==='object'&&value.content&&Array.isArray(value.content)){
  const texts=value.content.filter(c=>c.type==='text').map(c=>c.text).join('');
  try{value=JSON.parse(texts);}catch{return [];}
 }
 const rows=Array.isArray(value)?value:[value];
 return rows.flatMap(r=>r&&r.json?[r.json]:r&&typeof r==='object'?[r]:[]).flatMap(r=>r.body!==undefined?(Array.isArray(r.body)?r.body:[r.body]):[r]);
}
const turn=safeNode('Validate chat input')||{},begin=safeNode('Begin audited turn')||{};
const result=$input.first().json;
const steps=Array.isArray(result.intermediateSteps)?result.intermediateSteps:[];
const results=name=>steps.filter(s=>s.action?.tool===name).flatMap(s=>observation(s.observation));
const commits=results('create_confirmed_ticket').filter(r=>r.ok===true&&/^SUP-[0-9]{6,}$/.test(r.ticket_id||''));
const created=commits.at(-1);
const articles=results('search_knowledge_base').filter(r=>typeof r.article_id==='string'&&typeof r.content==='string');
const proposals=results('propose_ticket').filter(r=>r.ok===true&&['proposal_staged','existing_proposal'].includes(r.result));
const cancelled=results('cancel_ticket_proposal').some(r=>r.ok===true&&r.result==='proposal_cancelled');
const statuses=results('get_ticket_status').filter(r=>/^SUP-[0-9]{6,}$/.test(r.ticket_id||''));
const validNumbers=new Set([...commits,...statuses,...results('get_my_open_tickets')].map(r=>r.ticket_id).filter(x=>typeof x==='string'));
const fallback="I couldn't complete that safely. Please try again shortly. I cannot confirm a new ticket or team notification from this reply.";
let reply=fallback,clear=Boolean(created);
if(begin.allowed!==true){
 reply=begin.reason==='cached'&&typeof begin.cached_reply==='string'?begin.cached_reply:
 begin.reason==='busy'?'I am still handling your previous message. Please wait a moment before trying again.':
 begin.reason==='rate_limit'?'You have reached the chat rate limit. Please wait a minute and try again.':
 'Support is temporarily unavailable. I could not confirm that your message was saved. Please try again shortly.';
}else{
 try{
  if(result.error||typeof result.output!=='string'||!result.output.trim()||result.output.length>6000)throw Error('invalid result');
  if(/max.?iterations|iteration limit|agent stopped/i.test(result.output))throw Error('iteration limit');
  const a=JSON.parse(result.output);
  if(typeof a.reply!=='string'||!a.reply.trim()||a.reply.length>4000)throw Error('invalid reply');
  const text=a.reply.normalize('NFKC');
  const mentioned=text.match(/SUP-[0-9]+/gi)||[];
  if(mentioned.some(id=>!validNumbers.has(id.toUpperCase())))throw Error('unverified ticket');
  if(/(?:refund(?:ed)?|account (?:changed|updated|deleted)|password (?:reset|changed)|email (?:sent|delivered))\b/i.test(text)
     && /\b(?:I|we|have|has|was|been|successfully|done|completed|processed|issued)\b/i.test(text))throw Error('forbidden action');
  if(/(?:ticket.{0,25}(?:created|opened|logged)|(?:created|opened|logged).{0,25}ticket)/i.test(text)&&!created)throw Error('no create evidence');
  if(/(?:team.{0,25}(?:notified|alerted)|(?:notified|alerted).{0,25}team)/i.test(text)&&!commits.some(r=>r.notified===true))throw Error('no notification evidence');
  switch(a.kind){
   case 'answer':{
    if(!articles.length||!Array.isArray(a.answer_blocks)||a.answer_blocks.length<1||a.answer_blocks.length>3)throw Error('missing KB');
    reply=a.answer_blocks.map(b=>{
      const article=articles.find(r=>r.article_id===b.article_id),q=typeof b.quote==='string'?b.quote.trim():'';
      if(!article||q.length<15||q.length>1400||!article.content.includes(q))throw Error('ungrounded');
      return q+'\n[KB: '+article.article_id+']';
    }).join('\n\n');break;
   }
   case 'no_answer':{
    if(!steps.some(s=>s.action?.tool==='search_knowledge_base'))throw Error('search not attempted');
    reply='I could not find an approved knowledge-base answer to that question. I do not want to guess. Please tell me if something is still not working.';break;
   }
   case 'proposal':{
    const p=proposals.at(-1);if(!p||typeof p.summary!=='string')throw Error('no proposal evidence');
    reply='Here is the issue I would report:\n'+p.summary+'\n\nWould you like me to open a support ticket for this unresolved issue? Reply Yes to confirm or No to cancel.';break;
   }
   case 'cancelled':if(!cancelled)throw Error('no cancellation evidence');reply='I will not create a ticket from that proposed summary. Tell me what needs correcting or how else I can help.';break;
   case 'ticket':{
    if(!created)throw Error('no commit evidence');
    reply='Your ticket '+created.ticket_id+(created.new_ticket?' has been created.':' has been updated or reused for this issue.');
    reply+=created.notified===true?' The support team has been notified.':' I could not confirm team notification. Your ticket is saved.';
    if(created.notification_recorded===false)reply+=' The notification delivery record could not be updated.';
    break;
   }
   case 'status':{
    const s=statuses.at(-1);if(!s||!['open','pending','escalated','resolved','closed'].includes(s.status))throw Error('no status evidence');
    reply='Ticket '+s.ticket_id+' has status '+s.status+'.';break;
   }
   case 'smalltalk':reply='Hi! Tell me what you need help with. Please do not share passwords, API keys or payment-card details.';break;
   case 'clarify':reply='Please describe what is not working, any error message, and what you have already tried. Is the issue still unresolved?';break;
   case 'resolved':{
    if(!/\b(resolved|fixed|working now|solved)\b/i.test(turn.message||''))throw Error('resolution not explicit');
    reply='Glad to hear this is resolved. Let me know if you need help with anything else.';clear=true;break;
   }
   case 'handoff':reply='A human on the support team would need to handle that request. I cannot issue refunds, change accounts, reset passwords or send emails. Please describe the unresolved issue if you would like to discuss a support ticket.';break;
   default:throw Error('unknown kind');
  }
  if(!reply||reply.length>6000)throw Error('invalid rendered reply');
  const rendered=reply.normalize('NFKC');
  if((rendered.match(/SUP-[0-9]+/gi)||[]).some(id=>!validNumbers.has(id.toUpperCase())))throw Error('unverified rendered ticket');
  if(/(?:ticket.{0,25}(?:created|opened|logged)|(?:created|opened|logged).{0,25}ticket)/i.test(rendered)&&!created)throw Error('unverified rendered creation');
  if(/(?:team.{0,25}(?:notified|alerted)|(?:notified|alerted).{0,25}team)/i.test(rendered)&&!commits.some(r=>r.notified===true))throw Error('unverified rendered notification');
 }catch{reply=fallback;}
}
return [{json:{reply,pending_action:clear?'clear':'keep'}}];

