function slackTicket(ticket){
 const TEAM_TARGETS={
 account_basics:{label:'Customer Support',id:'<YOUR_SLACK_OWNER_ID>'},
 billing:{label:'Billing Team',id:'<YOUR_SLACK_OWNER_ID>'},
 features:{label:'Product Support',id:'<YOUR_SLACK_OWNER_ID>'},
 troubleshooting:{label:'Technical Support',id:'<YOUR_SLACK_OWNER_ID>'},
 integrations:{label:'Integrations Team',id:'<YOUR_SLACK_OWNER_ID>'},
 policies:{label:'Support Lead',id:'<YOUR_SLACK_OWNER_ID>'}
 };
 const target=TEAM_TARGETS[ticket.category]||TEAM_TARGETS.troubleshooting;
 const tag=/^S[A-Z0-9]+$/.test(target.id)?'<!subteam^'+target.id+'>':/^[UW][A-Z0-9]+$/.test(target.id)?'<@'+target.id+'>':target.label+' (configure team tag)';
 const esc=(s,n)=>String(s||'').slice(0,n).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/[\\*_~\x60]/g,'');
 return {text:tag+'\nSupport ticket '+esc(ticket.ticket_id,40)+'\nPriority: '+esc(ticket.priority,20)+' | Category: '+esc(ticket.category,40)+
 '\n'+esc(ticket.subject,200)+'\n'+esc(ticket.summary,2500)+(ticket.needs_human_review?'\nNeeds human review: classification confidence was low.':'')+
 '\nNotification only. No refund, account change or other action has been performed.'};
}
return [{json:slackTicket($('Commit confirmed ticket').first().json)}];

function safe(name){try{return $(name).isExecuted?$(name).first().json:null;}catch{return null;}}
const t=safe('Commit confirmed ticket')||{};
if(!/^SUP-[0-9]{6,}$/.test(t.ticket_id||'')||t.rate_limited!==false){
 return [{json:{ok:false,refused:true,reason:t.rate_limited===true?'Ticket creation limit reached. Please wait before trying again.':'Ticket confirmation could not be verified. An active unexpired proposal and literal customer confirmation are required. A network failure can leave the outcome uncertain; retry only the same proposal.'}}];
}
const checked=safe('Check team notification'),record=safe('Record alert status');
const notified=t.notification_status==='sent'||checked?.sent===true;
return [{json:{ok:true,ticket_id:t.ticket_id,new_ticket:t.new_ticket===true,notified,
 notification_recorded:record?record.ticket_id===t.ticket_id&&record.notification_status===(notified?'sent':'failed'):t.notification_status==='sent',
 needs_human_review:t.needs_human_review===true}}];
